#include "conv_standard_3d_square_input_square_kernel_custom_tiling.h"
#include "register/op_def_registry.h"

namespace optiling {
static inline uint32_t floor_div(int64_t a, int64_t b) { return static_cast<uint32_t>(a / b); }
static inline uint32_t calc_out(uint32_t in, uint32_t k, uint32_t pad, uint32_t stride, uint32_t dilation) {
    // Standard conv output formula: floor((in + 2*pad - dilation*(k-1) - 1) / stride + 1)
    int64_t num = static_cast<int64_t>(in) + 2LL * pad - static_cast<int64_t>(dilation) * (static_cast<int64_t>(k) - 1) - 1;
    return static_cast<uint32_t>(num / static_cast<int64_t>(stride) + 1);
}

const uint32_t BLOCK_DIM = 8;
const uint32_t TILE_NUM = 8;

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    auto *x_shape = context->GetInputShape(0);
    auto *w_shape = context->GetInputShape(1);
    const auto &x_dims = x_shape->GetOriginShape();
    const auto &w_dims = w_shape->GetOriginShape();

    // Expect shapes:
    // x: [N, C_in, D, H, W]
    // w: [C_out, C_in, K, K, K] (square kernel)
    uint32_t n    = static_cast<uint32_t>(x_dims.GetDim(0));
    uint32_t c_in = static_cast<uint32_t>(x_dims.GetDim(1));
    uint32_t d    = static_cast<uint32_t>(x_dims.GetDim(2));
    uint32_t h    = static_cast<uint32_t>(x_dims.GetDim(3));
    uint32_t w    = static_cast<uint32_t>(x_dims.GetDim(4));

    uint32_t c_out = static_cast<uint32_t>(w_dims.GetDim(0));
    uint32_t k     = static_cast<uint32_t>(w_dims.GetDim(2)); // K (square)

    // Defaults for stride/pad/dilation; this sample assumes stride=1, pad=0, dilation=1
    uint32_t stride   = 1;
    uint32_t pad      = 0;
    uint32_t dilation = 1;

    uint32_t d_out = calc_out(d, k, pad, stride, dilation);
    uint32_t h_out = calc_out(h, k, pad, stride, dilation);
    uint32_t w_out = calc_out(w, k, pad, stride, dilation);

    ConvStandard3dSquareInputSquareKernelCustomTilingData tiling;
    tiling.set_n(n);
    tiling.set_c_in(c_in);
    tiling.set_d(d);
    tiling.set_h(h);
    tiling.set_w(w);

    tiling.set_c_out(c_out);
    tiling.set_k(k);

    tiling.set_stride(stride);
    tiling.set_pad(pad);
    tiling.set_dilation(dilation);

    tiling.set_d_out(d_out);
    tiling.set_h_out(h_out);
    tiling.set_w_out(w_out);

    context->SetBlockDim(BLOCK_DIM);
    tiling.set_tileNum(TILE_NUM);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());
    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
} // namespace optiling

namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    const gert::Shape* x_shape = context->GetInputShape(0);
    const gert::Shape* w_shape = context->GetInputShape(1);

    auto x_dims = x_shape->GetOriginShape();
    auto w_dims = w_shape->GetOriginShape();

    uint32_t N    = static_cast<uint32_t>(x_dims.GetDim(0));
    uint32_t Cin  = static_cast<uint32_t>(x_dims.GetDim(1));
    uint32_t D    = static_cast<uint32_t>(x_dims.GetDim(2));
    uint32_t H    = static_cast<uint32_t>(x_dims.GetDim(3));
    uint32_t W    = static_cast<uint32_t>(x_dims.GetDim(4));
    uint32_t Cout = static_cast<uint32_t>(w_dims.GetDim(0));
    uint32_t K    = static_cast<uint32_t>(w_dims.GetDim(2));

    // Default: stride=1, pad=0, dilation=1
    auto calc_out = [](uint32_t in, uint32_t k, uint32_t pad, uint32_t stride, uint32_t dilation) -> uint32_t {
        int64_t num = static_cast<int64_t>(in) + 2LL * pad - static_cast<int64_t>(dilation) * (static_cast<int64_t>(k) - 1) - 1;
        return static_cast<uint32_t>(num / static_cast<int64_t>(stride) + 1);
    };

    uint32_t Dout = calc_out(D, K, 0, 1, 1);
    uint32_t Hout = calc_out(H, K, 0, 1, 1);
    uint32_t Wout = calc_out(W, K, 0, 1, 1);

    gert::Shape* y_shape = context->GetOutputShape(0);
    gert::Shape newY({(int64_t)N, (int64_t)Cout, (int64_t)Dout, (int64_t)Hout, (int64_t)Wout});
    *y_shape = newY;
    return GRAPH_SUCCESS;
}

static ge::graphStatus InferDataType(gert::InferDataTypeContext *context)
{
    const auto inputDataType = context->GetInputDataType(0);
    context->SetOutputDataType(0, inputDataType);
    return ge::GRAPH_SUCCESS;
}
} // namespace ge

